{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "Rufinamide absolute oral bioavailability is 85% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C77"],
      "claim": "Niraparib absolute oral bioavailability was 72.7% (90% CI 61.69–83.40) after a 300 mg oral dose versus IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Tofogliflozin mean absolute bioavailability was 97.5% in healthy male volunteers using a double-tracer IV microdosing technique, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All supplied evidence molecules have molecule-level directions supporting high bioavailability; strongest adult absolute F values range from about 73% to 97.5%, all well above the 20% threshold. Low didanosine values in fed/pediatric settings are discounted as altered or special conditions.",
  "evidence_gaps": [
    "Some didanosine records report F below 20% in fed state or children, but these are not the strongest ordinary adult absolute measurements; they introduce population/condition uncertainty.",
    "Salicin numeric bioavailability was measured relative to acetylsalicylic acid rather than IV, so its endpoint directness is lower."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

